    14	function CodeRenderer({TDefaultRenderer, key, style, ...defaultRendererProps}: CodeRendererProps) {
    15	    const StyleUtils = useStyleUtils();
    16	    // We split wrapper and inner styles
    17	    // "boxModelStyle" corresponds to border, margin, padding and backgroundColor
    18	    const {boxModelStyle, otherStyle: textStyle} = splitBoxModelStyle(style ?? {});
    19	
    20	    /** Get the default fontFamily variant */
    21	    const font = FontUtils.fontFamily.platform.MONOSPACE.fontFamily;
