    24	    const isInsideH1 = HTMLEngineUtils.isChildOfH1(defaultRendererProps.tnode);
    25	
    26	    const fontSize = StyleUtils.getCodeFontSize(isInsideH1);
    27	
    28	    const textStyleOverride = {
    29	        fontSize,
    30	        fontFamily: font,
    31	
    32	        // We need to override this properties bellow that was defined in `textStyle`
    33	        // Because by default the `react-native-render-html` add a style in the elements,
    34	        // for example the <strong> tag has a fontWeight: "bold" and in the android it break the font
